-- review-service initial schema and seed data.
-- Owns the `reviews` table inside `review_schema`.
--
-- Business rule: at most one review per (user, property). Enforced both in
-- service code and at the DB level via the unique constraint below.

CREATE TABLE reviews (
    id           UUID         PRIMARY KEY,
    property_id  UUID         NOT NULL,
    user_id      UUID         NOT NULL,
    rating       SMALLINT     NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment      TEXT         NOT NULL,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT reviews_user_property_unique UNIQUE (user_id, property_id)
);

CREATE INDEX idx_reviews_property ON reviews (property_id);
CREATE INDEX idx_reviews_user     ON reviews (user_id);

-- ----------------------------------------------------------------------------
-- Seed: 50 reviews across the 20 properties from property-service. Ratings are
-- biased toward 4-5 (matches the property ratings) but include 1-2 stars too so
-- aggregations exercise the full domain.
-- Property UUIDs use the `11111111-` prefix; user UUIDs use the `33333333-` prefix.
-- Review UUIDs use the `44444444-` prefix to keep them distinguishable.
-- ----------------------------------------------------------------------------

